from __future__ import absolute_import

from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts.pages import v22r2
from taf.selenium.sbts.pages.modals import RestoreDefaultModal
from taf.selenium.sbts.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts.pages.panels.view import ViewPanel


class Diagnostic(v22r2.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._snapshot_configuration = SnapshotConfigurationPage(driver)

    @property
    def snapshot_configuration(self):
        return self._snapshot_configuration


class SnapshotConfigurationPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Snapshot', 'Snapshot Configuration']

    def __init__(self, driver):
        super(SnapshotConfigurationPage, self).__init__(driver)
        self._view_panel = SnapshotConfigurationPageViewPanel(driver)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_snapshot_default_fault_list(self, timeout=60):
        return self._view_panel.get_snapshot_default_fault_list(timeout)

    def get_fault_snapshot_trigger_list(self, timeout):
        return self._view_panel.get_fault_snapshot_trigger_list(timeout)

    def activate_or_restore_default_faults(self, activate=True, restore=True, timeout=60):
        self._view_panel.activate_or_restore_default_faults(activate, restore, timeout)

    def delete_fault_snapshot_from_trigger_list(self, fault_number, timeout=60):
        self._view_panel.delete_fault_snapshot_trigger_list(fault_number, timeout)

    def modify_fault_snapshot_trigger_list(self, fault_number, new_fault_number=None, trigger_type=None, timeout=60):
        self._view_panel.modify_fault_snapshot_trigger_list(fault_number,
                                                            new_fault_number,
                                                            trigger_type,
                                                            timeout)

    def send_snapshot_configuration(self, timeout):
        return self._view_panel.send_snapshot_configuration(timeout)


class SnapshotConfigurationPageViewPanel(ViewPanel):
    _DEFAULT_FAULT_LIST = '//default-fault-list//table'
    _FAULT_SNAPSHOT_TRIGGER_LIST = '//fault-snapshot-trigger-list//table'
    _DEFAULT_TRIGGER = _FAULT_SNAPSHOT_TRIGGER_LIST + '//tbody//tr//td[2]'
    _FAULT_NUMBER = 'fault-snapshot-trigger-list tbody tr td:nth-child(3) input'
    _TRIGGER_TYPE = _FAULT_SNAPSHOT_TRIGGER_LIST + '//tbody//tr//td[4]//p-dropdown'
    _ACTIVATE_FAULTS = '//fault-snapshot-trigger-list//div[contains(@class, "p-checkbox-box")]'
    _RESTORE_BUTTON = '//button[*[text()="Restore Default"]]'
    _REMOVE_BUTTON = _FAULT_SNAPSHOT_TRIGGER_LIST + '//td[*[@*="{}"]]/parent::tr//button[@title="Remove"]'
    _FAULT_NUMBER_MODIFY = _FAULT_SNAPSHOT_TRIGGER_LIST + '//td[*[@*="{}"]]//input'
    _TRIGGER_TYPE_DROPDOWN_BUTTON = _FAULT_SNAPSHOT_TRIGGER_LIST + ('//td[*[@*="{}"]]/parent::tr//td[4]'
                                                                    '//p-dropdown//*[@role="button"]')
    _TRIGGER_TYPE_DROPDOWN_LIST = '//ul[@role="listbox"]//*[text()="{}"]'
    _SEND_BUTTON_XPATH = '//div[contains(@class, "snapshot-configuration")]//button[*[text()="Send"]]'
    _SEND_STATUS = '//ot-instruction//span'
    _SUCCESS = 'Success'

    def __init__(self, driver):
        super(SnapshotConfigurationPageViewPanel, self).__init__(driver)

    def get_snapshot_default_fault_list(self, timeout=60):
        self.wait_for_visibility_by_xpath(self._DEFAULT_FAULT_LIST, timeout)
        th_elems = self.driver.find_elements_by_xpath(self._DEFAULT_FAULT_LIST + '//thead//th')
        columns_title = [elem.text.strip() for elem in th_elems]

        table_info = []
        tr_elems = self.driver.find_elements_by_xpath(self._DEFAULT_FAULT_LIST + '//tbody//tr')

        for tr_elem in tr_elems:
            values = []
            for tr_elem in tr_elem.find_elements_by_xpath('.//td'):
                values.append(tr_elem.text.strip())
            table_info.append(dict(zip(columns_title, values)))
        return table_info

    def activate_or_restore_default_faults(self, activate, restore, timeout=60):
        elem = self.wait_for_enable((By.XPATH, self._ACTIVATE_FAULTS), timeout)
        if 'highlight' in elem.get_attribute('class') and not activate:
            elem.click()

        if 'highlight' not in elem.get_attribute('class') and activate:
            elem.click()

        if restore:
            self.click_enabled_element((By.XPATH, self._RESTORE_BUTTON), timeout)
            restore_modal = RestoreDefaultModal(self.driver)
            restore_modal.confirm(timeout)

    def get_fault_snapshot_trigger_list(self, timeout=60):
        self.wait_for_visibility_by_xpath(self._FAULT_SNAPSHOT_TRIGGER_LIST, timeout)
        th_elems = self.driver.find_elements_by_xpath(self._FAULT_SNAPSHOT_TRIGGER_LIST + '//thead//th')
        columns_title = []
        for elem in th_elems:
            value = elem.text.strip()
            if value:
                columns_title.append(value)

        default_trigger = [elem.text.strip() for elem in self.driver.find_elements_by_xpath(self._DEFAULT_TRIGGER)]

        fault_numbers = []
        for _ in range(len(default_trigger)):
            value = self.driver.execute_script('return document.querySelector("{}").value'.format(self._FAULT_NUMBER))
            fault_numbers.append(value)

        trigger_type = [elem.get_attribute('title').strip() for elem in
                        self.driver.find_elements_by_xpath(self._TRIGGER_TYPE)]

        table_info = []
        for trigger, number, tt in zip(default_trigger, fault_numbers, trigger_type):
            table_info.append(dict(zip(columns_title, [trigger, number, tt])))
        return table_info

    def delete_fault_snapshot_trigger_list(self, fault_number, timeout=60):
        self.click_enabled_element((By.XPATH, self._REMOVE_BUTTON.format(fault_number)), timeout)

    def modify_fault_snapshot_trigger_list(self, fault_number, new_fault_number=None, trigger_type=None, timeout=60):
        if new_fault_number and trigger_type:
            self.select_element_from_dropdown_list_by_text_and_click(
                trigger_type,
                (By.XPATH, self._TRIGGER_TYPE_DROPDOWN_BUTTON.format(fault_number)),
                (By.XPATH, self._TRIGGER_TYPE_DROPDOWN_LIST.format(trigger_type))
            )
            self.insert_text_to_enable_element((By.XPATH, self._FAULT_NUMBER_MODIFY.format(fault_number)),
                                               new_fault_number,
                                               timeout)

        if not new_fault_number and trigger_type:
            self.select_element_from_dropdown_list_by_text_and_click(
                trigger_type,
                (By.XPATH, self._TRIGGER_TYPE_DROPDOWN_BUTTON.format(fault_number)),
                (By.XPATH, self._TRIGGER_TYPE_DROPDOWN_LIST.format(trigger_type))
            )

        if new_fault_number and not trigger_type:
            self.insert_text_to_enable_element((By.XPATH, self._FAULT_NUMBER_MODIFY.format(fault_number)),
                                               new_fault_number,
                                               timeout)

    def send_snapshot_configuration(self, timeout=60):
        self.click_enabled_element((By.XPATH, self._SEND_BUTTON_XPATH), timeout)
        try:
            self.wait_for_text_present_in_element((By.XPATH, self._SEND_STATUS), self._SUCCESS, timeout)
            return self._SUCCESS
        except TimeoutException:
            return self.get_text_by_xpath(self._SEND_STATUS, timeout)
